$$
\begin{aligned}\frac{4a+10b-12c}{8} & = \\ \frac{4a}{8}+\frac{10b}{8}-\frac{12c}{8} & = \\ \frac{4}{8}\cdot a+\frac{10}{8}\cdot b-\frac{12}{8}\cdot c & = \\ \frac{1}{2}\cdot a+\frac{5}{4}\cdot b-\frac{3}{2}\cdot c & = \\ \frac{a}{2}+\frac{5b}{4}-\frac{3c}{2} & .\end{aligned}
$$

$$
\begin{aligned}\frac{2x-3y+8z}{6} & = \\ \frac{2x}{6}-\frac{3y}{6}+\frac{8z}{6} & = \\ \frac{2}{6}\cdot x-\frac{3}{6}\cdot y+\frac{8}{6}\cdot z & = \\ \frac{1}{3}\cdot x-\frac{1}{2}\cdot y+\frac{4}{3}\cdot z & = \\ \frac{x}{3}-\frac{y}{2}+\frac{4z}{3} & .\end{aligned}
$$

$$
\begin{aligned}\frac{5x-10y-2z}{5} & = \\ \frac{5x}{5}-\frac{10y}{5}-\frac{2z}{5} & = \\ \frac{5}{5}\cdot x-\frac{10}{5}\cdot y-\frac{2}{5}\cdot z & = \\ 1\cdot x-2\cdot y-\frac{2}{5}\cdot z & = \\ x-2y-\frac{2z}{5} & .\end{aligned}
$$
